            "functional": {
              "type": "offering"
            }
          }
        ]
      }
    },
    {
      "kind": "fill_room",
      "payload": {
        "area_id": "frontier_town",
        "location_id": "mother_earth_temple",
        "room_id": "confession_room",
        "name": "忏悔室",
        "description": "一间狭小而昏暗的木质房间，中间被一道细密的格栅屏风隔开。这里是冒险者们吐露内心恐惧与罪孽的避风港。",
        "interactables": [
          {
            "id": "confession_grille",
            "name": "忏悔格栅",
            "description": "透着微弱光线的木格栅，屏风另一端似乎总有一位耐心的倾听者。",
